-- RAWAEA ERP — TASK-028 FINAL RELEASE MIGRATION
-- One coherent deployable migration for Loading lifecycle.
-- Includes central stock boundary, event idempotency, lifecycle RPCs,
-- backorder ledger, trigger integrity, and privilege hardening.
BEGIN;
CREATE TABLE IF NOT EXISTS public.fulfillment_backorders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),order_id uuid NOT NULL REFERENCES public.orders(id),order_detail_id uuid NOT NULL REFERENCES public.order_details(id),runsheet_id uuid NOT NULL REFERENCES public.runsheets(id),item_id uuid NOT NULL REFERENCES public.items(id),item_code varchar,remaining_qty numeric NOT NULL CHECK(remaining_qty>0),status varchar NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Cancelled','Consumed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_detail_id,runsheet_id));
CREATE INDEX IF NOT EXISTS idx_fulfillment_backorders_order ON public.fulfillment_backorders(order_id,status); CREATE INDEX IF NOT EXISTS idx_fulfillment_backorders_runsheet ON public.fulfillment_backorders(runsheet_id,status); ALTER TABLE public.fulfillment_backorders ENABLE ROW LEVEL SECURITY; REVOKE ALL ON TABLE public.fulfillment_backorders FROM PUBLIC,anon; GRANT ALL ON TABLE public.fulfillment_backorders TO service_role;
ALTER TABLE public.inventory_log ADD COLUMN IF NOT EXISTS idempotency_key text; CREATE UNIQUE INDEX IF NOT EXISTS ux_inventory_log_company_idempotency ON public.inventory_log(company_id,idempotency_key) WHERE idempotency_key IS NOT NULL; CREATE UNIQUE INDEX IF NOT EXISTS ux_run_sheet_details_runsheet_item ON public.run_sheet_details(runsheet_id,item_code);
CREATE OR REPLACE FUNCTION public.sync_run_sheet_details() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r_id uuid;i_id uuid;c text;BEGIN IF TG_OP='DELETE' THEN c:=OLD.item_code;SELECT runsheet_id INTO r_id FROM public.orders WHERE id=OLD.order_id;ELSE c:=NEW.item_code;SELECT runsheet_id INTO r_id FROM public.orders WHERE id=NEW.order_id;END IF;IF r_id IS NULL THEN IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END IF;SELECT id INTO i_id FROM public.items WHERE item_code=c LIMIT 1;INSERT INTO public.run_sheet_details(runsheet_id,item_id,item_code,item_name,unit,unit_price,qty_ordered,qty_picked,qty_loaded,qty_delivered,qty_refused,qty_returned,driver_liability) SELECT r_id,i_id,c,MAX(od.item_name),MAX(od.unit),MAX(od.unit_price),COALESCE(SUM(od.qty),0),COALESCE(SUM(od.qty_picked),0),COALESCE(SUM(od.qty_loaded),0),COALESCE(SUM(od.qty_delivered),0),COALESCE(SUM(od.qty_refused),0),COALESCE(SUM(od.qty_returned),0),COALESCE(SUM(od.driver_liability),0) FROM public.order_details od JOIN public.orders o ON od.order_id=o.id WHERE o.runsheet_id=r_id AND od.item_code=c ON CONFLICT(runsheet_id,item_code) DO UPDATE SET item_id=EXCLUDED.item_id,item_name=EXCLUDED.item_name,unit=EXCLUDED.unit,unit_price=EXCLUDED.unit_price,qty_ordered=EXCLUDED.qty_ordered,qty_picked=EXCLUDED.qty_picked,qty_loaded=EXCLUDED.qty_loaded,qty_delivered=EXCLUDED.qty_delivered,qty_refused=EXCLUDED.qty_refused,qty_returned=EXCLUDED.qty_returned,driver_liability=EXCLUDED.driver_liability,updated_at=now();RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END;$$;
DROP TRIGGER IF EXISTS trg_sync_run_sheet_details ON public.order_details; CREATE TRIGGER trg_sync_run_sheet_details AFTER INSERT OR DELETE OR UPDATE ON public.order_details FOR EACH ROW EXECUTE FUNCTION public.sync_run_sheet_details();
CREATE OR REPLACE FUNCTION public.post_stock_movement(p_company_id uuid,p_movement_type text,p_source_branch_id uuid,p_target_branch_id uuid,p_item_id uuid,p_qty numeric,p_voucher_id text,p_reference text,p_user_email text,p_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.stock_branches%ROWTYPE;t public.stock_branches%ROWTYPE;e public.inventory_log%ROWTYPE;bc uuid;av numeric;BEGIN IF p_company_id IS NULL OR p_movement_type IS NULL OR p_qty IS NULL OR p_qty<=0 THEN RAISE EXCEPTION 'invalid movement request';END IF;IF p_movement_type NOT IN('PurchaseIn','TransferOut','TransferIn','DirectSale','DirectReturn','SupplierReturn','POSSale','VanSale','SalesReturn','PurchaseReturn','InventoryIncrease','InventoryDecrease','Loading','Unloading') THEN RAISE EXCEPTION 'movement type is not supported: %',p_movement_type;END IF;IF p_movement_type IN('Loading','Unloading') AND NULLIF(btrim(p_idempotency_key),'') IS NULL THEN RAISE EXCEPTION 'event-level idempotency_key required';END IF;IF p_idempotency_key IS NOT NULL THEN SELECT * INTO e FROM public.inventory_log WHERE company_id=p_company_id AND idempotency_key=p_idempotency_key LIMIT 1;IF FOUND THEN IF e.movement_type<>p_movement_type OR e.qty<>p_qty THEN RAISE EXCEPTION 'idempotency key conflict';END IF;RETURN jsonb_build_object('success',true,'duplicate',true,'log_code',e.log_code);END IF;END IF;IF p_source_branch_id IS NOT NULL THEN SELECT company_id INTO bc FROM public.branches WHERE id=p_source_branch_id;IF bc IS NULL OR bc<>p_company_id THEN RAISE EXCEPTION 'source branch context invalid';END IF;END IF;IF p_target_branch_id IS NOT NULL THEN SELECT company_id INTO bc FROM public.branches WHERE id=p_target_branch_id;IF bc IS NULL OR bc<>p_company_id THEN RAISE EXCEPTION 'target branch context invalid';END IF;END IF;IF NOT EXISTS(SELECT 1 FROM public.items WHERE id=p_item_id AND company_id=p_company_id) THEN RAISE EXCEPTION 'item context invalid';END IF;PERFORM 1 FROM public.stock_branches x WHERE x.item_id=p_item_id AND x.branch_id IN(p_source_branch_id,p_target_branch_id) ORDER BY x.branch_id FOR UPDATE;IF p_idempotency_key IS NOT NULL THEN SELECT * INTO e FROM public.inventory_log WHERE company_id=p_company_id AND idempotency_key=p_idempotency_key LIMIT 1;IF FOUND THEN RETURN jsonb_build_object('success',true,'duplicate',true,'log_code',e.log_code);END IF;END IF;IF p_source_branch_id IS NOT NULL THEN SELECT * INTO s FROM public.stock_branches WHERE branch_id=p_source_branch_id AND item_id=p_item_id;IF NOT FOUND THEN RAISE EXCEPTION 'source stock row missing';END IF;av:=COALESCE(s.qty,0)-COALESCE(s.allocated_qty,0);IF p_movement_type='Loading' THEN IF COALESCE(s.qty,0)<p_qty OR COALESCE(s.allocated_qty,0)<p_qty THEN RAISE EXCEPTION 'insufficient picked reservation';END IF;ELSIF p_movement_type='Unloading' THEN IF COALESCE(s.qty,0)<p_qty THEN RAISE EXCEPTION 'insufficient source stock';END IF;ELSIF av<p_qty THEN RAISE EXCEPTION 'insufficient available stock';END IF;END IF;IF p_target_branch_id IS NOT NULL THEN SELECT * INTO t FROM public.stock_branches WHERE branch_id=p_target_branch_id AND item_id=p_item_id;IF NOT FOUND THEN RAISE EXCEPTION 'target stock row missing';END IF;END IF;IF p_source_branch_id IS NOT NULL THEN UPDATE public.stock_branches SET qty=s.qty-p_qty,allocated_qty=CASE WHEN p_movement_type='Loading' THEN s.allocated_qty-p_qty ELSE s.allocated_qty END,updated_at=now() WHERE id=s.id AND qty=s.qty AND allocated_qty=s.allocated_qty;IF NOT FOUND THEN RAISE EXCEPTION 'source stock changed';END IF;END IF;IF p_target_branch_id IS NOT NULL THEN UPDATE public.stock_branches SET qty=t.qty+p_qty,allocated_qty=CASE WHEN p_movement_type='Unloading' THEN t.allocated_qty+p_qty ELSE t.allocated_qty END,updated_at=now() WHERE id=t.id AND qty=t.qty AND allocated_qty=t.allocated_qty;IF NOT FOUND THEN RAISE EXCEPTION 'target stock changed';END IF;END IF;INSERT INTO public.inventory_log(company_id,log_code,movement_date,voucher_id,item_id,movement_type,qty,reference,user_email,idempotency_key) VALUES(p_company_id,'STM-'||replace(gen_random_uuid()::text,'-',''),CURRENT_DATE,p_voucher_id,p_item_id,p_movement_type,p_qty,p_reference,p_user_email,p_idempotency_key);RETURN jsonb_build_object('success',true,'duplicate',false,'movement_type',p_movement_type,'qty',p_qty);END;$$;
CREATE OR REPLACE FUNCTION public.post_stock_movement(p_company_id uuid,p_movement_type text,p_source_branch_id uuid,p_target_branch_id uuid,p_item_id uuid,p_qty numeric,p_voucher_id text,p_reference text,p_user_email text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_movement_type IN('Loading','Unloading') THEN RAISE EXCEPTION 'Loading/Unloading require idempotency key';END IF;RETURN public.post_stock_movement(p_company_id,p_movement_type,p_source_branch_id,p_target_branch_id,p_item_id,p_qty,p_voucher_id,p_reference,p_user_email,NULL);END;$$;
CREATE OR REPLACE FUNCTION public.start_runsheet_loading(p_company_id uuid,p_runsheet_code text,p_user_email text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.runsheets%ROWTYPE;u public.users%ROWTYPE;a text;BEGIN SELECT * INTO u FROM public.users WHERE email=p_user_email AND company_id=p_company_id LIMIT 1;IF NOT FOUND THEN RAISE EXCEPTION 'user is not registered in company';END IF;SELECT runsheet_code INTO a FROM public.runsheets WHERE company_id=p_company_id AND status='Loading' AND loader_id=u.id LIMIT 1;IF a IS NOT NULL THEN RAISE EXCEPTION 'user already has Loading runsheet: %',a;END IF;SELECT * INTO r FROM public.runsheets WHERE company_id=p_company_id AND runsheet_code=p_runsheet_code FOR UPDATE;IF NOT FOUND OR r.status<>'Picked' THEN RAISE EXCEPTION 'runsheet is not Picked';END IF;UPDATE public.runsheets SET status='Loading',loader_id=u.id,loader_start=now(),updated_at=now() WHERE id=r.id AND status='Picked';IF NOT FOUND THEN RAISE EXCEPTION 'start transition failed';END IF;RETURN jsonb_build_object('success',true,'runsheet_id',r.id,'status','Loading');END;$$;
CREATE OR REPLACE FUNCTION public.cancel_runsheet_loading(p_company_id uuid,p_runsheet_code text,p_user_email text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.runsheets%ROWTYPE;u public.users%ROWTYPE;BEGIN SELECT * INTO u FROM public.users WHERE email=p_user_email AND company_id=p_company_id LIMIT 1;IF NOT FOUND THEN RAISE EXCEPTION 'user is not registered in company';END IF;SELECT * INTO r FROM public.runsheets WHERE company_id=p_company_id AND runsheet_code=p_runsheet_code FOR UPDATE;IF NOT FOUND OR r.status<>'Loading' OR r.loader_id<>u.id THEN RAISE EXCEPTION 'invalid Loading cancellation context';END IF;UPDATE public.order_details od SET qty_loaded=0,updated_at=now() FROM public.orders o WHERE od.order_id=o.id AND o.company_id=p_company_id AND o.runsheet_id=r.id AND COALESCE(od.qty_loaded,0)>0;UPDATE public.runsheets SET status='Picked',loader_id=NULL,loader_start=NULL,updated_at=now() WHERE id=r.id AND status='Loading';RETURN jsonb_build_object('success',true,'runsheet_id',r.id,'status','Picked');END;$$;
CREATE OR REPLACE FUNCTION public.complete_runsheet_loading(p_company_id uuid,p_runsheet_id uuid,p_items jsonb,p_user_email text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.runsheets%ROWTYPE;v public.vehicles%ROWTYPE;m uuid;van uuid;code text;req numeric;cap numeric;rem numeric;iid uuid;d record;hash text;keybase text;total numeric:=0;BEGIN SELECT * INTO r FROM public.runsheets WHERE id=p_runsheet_id FOR UPDATE;IF NOT FOUND OR r.company_id<>p_company_id OR r.status<>'Loading' OR r.vehicle_id IS NULL OR r.loader_start IS NULL THEN RAISE EXCEPTION 'invalid Loading context';END IF;SELECT * INTO v FROM public.vehicles WHERE id=r.vehicle_id AND company_id=p_company_id;IF NOT FOUND THEN RAISE EXCEPTION 'vehicle not found';END IF;SELECT main_branch_id INTO STRICT m FROM public.app_settings WHERE company_id=p_company_id;SELECT id INTO van FROM public.branches WHERE company_id=p_company_id AND branch_code='VAN-'||v.vehicle_code AND is_active=true LIMIT 1;IF van IS NULL THEN RAISE EXCEPTION 'VAN branch not found';END IF;SELECT md5(COALESCE(string_agg(x.item_code||':'||x.loaded_qty::text,'|' ORDER BY x.item_code),'')) INTO hash FROM jsonb_to_recordset(p_items) x(item_code text,loaded_qty numeric);keybase:='TASK-028|Loading|'||r.id::text||'|'||r.loader_start::text||'|'||COALESCE(r.loader_end::text,'NONE')||'|'||hash;FOR code,req IN SELECT x.item_code,SUM(x.loaded_qty) FROM jsonb_to_recordset(p_items) x(item_code text,loaded_qty numeric) GROUP BY x.item_code ORDER BY x.item_code LOOP SELECT id INTO iid FROM public.items WHERE company_id=p_company_id AND item_code=code LIMIT 1;IF iid IS NULL OR req<=0 THEN RAISE EXCEPTION 'invalid item request';END IF;SELECT COALESCE(SUM(GREATEST(COALESCE(od.qty_picked,0),0)),0) INTO cap FROM public.order_details od JOIN public.orders o ON o.id=od.order_id WHERE o.company_id=p_company_id AND o.runsheet_id=r.id AND od.item_code=code;IF req>cap THEN RAISE EXCEPTION 'loaded quantity exceeds picked capacity';END IF;UPDATE public.order_details od SET qty_loaded=0,updated_at=now() FROM public.orders o WHERE od.order_id=o.id AND o.company_id=p_company_id AND o.runsheet_id=r.id AND od.item_code=code;rem:=req;FOR d IN SELECT od.id,COALESCE(od.qty_picked,0) picked FROM public.order_details od JOIN public.orders o ON o.id=od.order_id WHERE o.company_id=p_company_id AND o.runsheet_id=r.id AND od.item_code=code AND COALESCE(od.qty_picked,0)>0 ORDER BY od.id FOR UPDATE OF od LOOP EXIT WHEN rem<=0;UPDATE public.order_details SET qty_loaded=LEAST(rem,d.picked),updated_at=now() WHERE id=d.id;rem:=rem-LEAST(rem,d.picked);END LOOP;IF rem<>0 THEN RAISE EXCEPTION 'failed to allocate loaded quantity';END IF;PERFORM public.post_stock_movement(p_company_id,'Loading',m,van,iid,req,r.runsheet_code,keybase||'|'||iid::text,p_user_email,keybase||'|'||iid::text);INSERT INTO public.fulfillment_backorders(company_id,order_id,order_detail_id,runsheet_id,item_id,item_code,remaining_qty,status) SELECT p_company_id,od.order_id,od.id,r.id,od.item_id,od.item_code,(od.qty-COALESCE(od.qty_loaded,0)),'Pending' FROM public.order_details od JOIN public.orders o ON o.id=od.order_id WHERE o.company_id=p_company_id AND o.runsheet_id=r.id AND od.item_code=code AND od.qty>COALESCE(od.qty_loaded,0) ON CONFLICT(order_detail_id,runsheet_id) DO UPDATE SET remaining_qty=EXCLUDED.remaining_qty,status='Pending',updated_at=now();total:=total+req;END LOOP;UPDATE public.runsheets SET status='Loaded',loader_end=now(),updated_at=now() WHERE id=r.id AND status='Loading';IF NOT FOUND THEN RAISE EXCEPTION 'Load transition failed';END IF;UPDATE public.orders SET order_status='Loaded',updated_at=now() WHERE company_id=p_company_id AND runsheet_id=r.id;RETURN jsonb_build_object('success',true,'runsheet_id',r.id,'loaded_total',total);END;$$;
CREATE OR REPLACE FUNCTION public.complete_runsheet_unloading(p_company_id uuid,p_runsheet_code text,p_user_email text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.runsheets%ROWTYPE;v public.vehicles%ROWTYPE;m uuid;van uuid;d record;BEGIN SELECT * INTO r FROM public.runsheets WHERE company_id=p_company_id AND runsheet_code=p_runsheet_code FOR UPDATE;IF NOT FOUND OR r.status<>'Loaded' THEN RAISE EXCEPTION 'runsheet not Loaded';END IF;SELECT * INTO v FROM public.vehicles WHERE id=r.vehicle_id AND company_id=p_company_id;IF NOT FOUND THEN RAISE EXCEPTION 'vehicle not found';END IF;SELECT main_branch_id INTO STRICT m FROM public.app_settings WHERE company_id=p_company_id;SELECT id INTO van FROM public.branches WHERE company_id=p_company_id AND branch_code='VAN-'||v.vehicle_code AND is_active=true LIMIT 1;IF van IS NULL THEN RAISE EXCEPTION 'VAN branch not found';END IF;FOR d IN SELECT item_id,qty_loaded FROM public.run_sheet_details WHERE runsheet_id=r.id AND COALESCE(qty_loaded,0)>0 ORDER BY item_id LOOP PERFORM public.post_stock_movement(p_company_id,'Unloading',van,m,d.item_id,d.qty_loaded,r.runsheet_code,r.runsheet_code||'|Unloading|'||r.id::text||'|'||d.item_id::text,p_user_email,'TASK-028|Unloading|'||r.id::text||'|'||d.item_id::text);END LOOP;UPDATE public.order_details od SET qty_loaded=0,updated_at=now() FROM public.orders o WHERE od.order_id=o.id AND o.company_id=p_company_id AND o.runsheet_id=r.id;UPDATE public.fulfillment_backorders SET status='Cancelled',updated_at=now() WHERE runsheet_id=r.id AND status='Pending';UPDATE public.runsheets SET status='Picked',loader_end=NULL,updated_at=now() WHERE id=r.id AND status='Loaded';UPDATE public.orders SET order_status='Pending',updated_at=now() WHERE company_id=p_company_id AND runsheet_id=r.id;RETURN jsonb_build_object('success',true,'status','Picked');END;$$;
CREATE OR REPLACE FUNCTION public.complete_runsheet_reopen_loading(p_company_id uuid,p_runsheet_code text,p_user_email text,p_operation_id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.runsheets%ROWTYPE;v public.vehicles%ROWTYPE;m uuid;van uuid;d record;k text;ex integer;BEGIN SELECT * INTO r FROM public.runsheets WHERE company_id=p_company_id AND runsheet_code=p_runsheet_code FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'runsheet not found';END IF;k:='TASK-028|ReopenLoading|'||p_operation_id||'|'||r.id::text;SELECT count(*) INTO ex FROM public.inventory_log WHERE company_id=p_company_id AND idempotency_key LIKE k||'|%';IF ex>0 THEN RETURN jsonb_build_object('success',true,'duplicate',true,'operation_id',p_operation_id);END IF;IF r.status<>'Loaded' THEN RAISE EXCEPTION 'runsheet not Loaded';END IF;SELECT * INTO v FROM public.vehicles WHERE id=r.vehicle_id AND company_id=p_company_id;IF NOT FOUND THEN RAISE EXCEPTION 'vehicle not found';END IF;SELECT main_branch_id INTO STRICT m FROM public.app_settings WHERE company_id=p_company_id;SELECT id INTO van FROM public.branches WHERE company_id=p_company_id AND branch_code='VAN-'||v.vehicle_code AND is_active=true LIMIT 1;IF van IS NULL THEN RAISE EXCEPTION 'VAN branch not found';END IF;FOR d IN SELECT item_id,qty_loaded FROM public.run_sheet_details WHERE runsheet_id=r.id AND COALESCE(qty_loaded,0)>0 ORDER BY item_id LOOP PERFORM public.post_stock_movement(p_company_id,'Unloading',van,m,d.item_id,d.qty_loaded,r.runsheet_code,r.runsheet_code||'|Reopen|'||p_operation_id||'|'||d.item_id::text,p_user_email,k||'|'||d.item_id::text);END LOOP;UPDATE public.runsheets SET status='Loading',loader_end=NULL,updated_at=now() WHERE id=r.id AND status='Loaded';RETURN jsonb_build_object('success',true,'duplicate',false,'qty_loaded_preserved',true,'operation_id',p_operation_id);END;$$;
REVOKE ALL ON FUNCTION public.post_stock_movement(uuid,text,uuid,uuid,uuid,numeric,text,text,text) FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.post_stock_movement(uuid,text,uuid,uuid,uuid,numeric,text,text,text,text) FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.start_runsheet_loading(uuid,text,text) FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.cancel_runsheet_loading(uuid,text,text) FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.complete_runsheet_loading(uuid,uuid,jsonb,text) FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.complete_runsheet_unloading(uuid,text,text) FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.complete_runsheet_reopen_loading(uuid,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.post_stock_movement(uuid,text,uuid,uuid,uuid,numeric,text,text,text) TO service_role; GRANT EXECUTE ON FUNCTION public.post_stock_movement(uuid,text,uuid,uuid,uuid,numeric,text,text,text,text) TO service_role; GRANT EXECUTE ON FUNCTION public.start_runsheet_loading(uuid,text,text) TO service_role; GRANT EXECUTE ON FUNCTION public.cancel_runsheet_loading(uuid,text,text) TO service_role; GRANT EXECUTE ON FUNCTION public.complete_runsheet_loading(uuid,uuid,jsonb,text) TO service_role; GRANT EXECUTE ON FUNCTION public.complete_runsheet_unloading(uuid,text,text) TO service_role; GRANT EXECUTE ON FUNCTION public.complete_runsheet_reopen_loading(uuid,text,text,text) TO service_role;
COMMIT;